func newEmbedding() unsafe.Pointer { return unsafe.Pointer(new(airetrieval.Embedding)) }

func newNEmbedding(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]airetrieval.Embedding, n)))
}

func ptrEmbedding(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.Embedding)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.SourceType))
	case 3:
		return (*string)(unsafe.Pointer(&r.SourceID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.ChunkIndex))
	case 5:
		return &r.ModelKey
	case 6:
		return (*int64)(unsafe.Pointer(&r.Dimensions))
	case 7:
		return &r.ContentHash
	case 8:
		return &r.Embedding
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueEmbedding(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.Embedding)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.SourceType)
	case 3:
		return string(r.SourceID)
	case 4:
		return int64(r.ChunkIndex)
	case 5:
		return r.ModelKey
	case 6:
		return int64(r.Dimensions)
	case 7:
		return r.ContentHash
	case 8:
		return r.Embedding
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

