func newIndexEntry() unsafe.Pointer { return unsafe.Pointer(new(airetrieval.IndexEntry)) }

func newNIndexEntry(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]airetrieval.IndexEntry, n)))
}

func ptrIndexEntry(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.IndexEntry)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.SourceType))
	case 3:
		return (*string)(unsafe.Pointer(&r.SourceID))
	case 4:
		return &r.ModelKey
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.Generation
	case 7:
		return (*int64)(unsafe.Pointer(&r.Attempts))
	case 8:
		return (*int64)(unsafe.Pointer(&r.ChunkCount))
	case 9:
		return &r.LastError
	case 10:
		return &r.LeaseExpiresAt
	case 11:
		return &r.NextAttemptAt
	case 12:
		return &r.LastAttemptAt
	case 13:
		return &r.IndexedAt
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valueIndexEntry(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.IndexEntry)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.SourceType)
	case 3:
		return string(r.SourceID)
	case 4:
		return r.ModelKey
	case 5:
		return string(r.Status)
	case 6:
		return r.Generation
	case 7:
		return int64(r.Attempts)
	case 8:
		return int64(r.ChunkCount)
	case 9:
		if r.LastError == "" {
			return nil
		}
		return r.LastError
	case 10:
		if r.LeaseExpiresAt == nil {
			return nil
		}
		return *r.LeaseExpiresAt
	case 11:
		if r.NextAttemptAt == nil {
			return nil
		}
		return *r.NextAttemptAt
	case 12:
		if r.LastAttemptAt == nil {
			return nil
		}
		return *r.LastAttemptAt
	case 13:
		if r.IndexedAt == nil {
			return nil
		}
		return *r.IndexedAt
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

