func ptrSettings(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.Settings)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.MemoryEnabled
	case 4:
		return &r.DocumentsEnabled
	case 5:
		return &r.InboundMessagesEnabled
	case 6:
		return &r.MonthlyIndexingBudgetUSD
	case 7:
		return &r.Paused
	case 8:
		return (*string)(unsafe.Pointer(&r.PausedReason))
	case 9:
		return &r.PausedAt
	case 10:
		return &r.ActiveModelKey
	case 11:
		return (*int64)(unsafe.Pointer(&r.Dimensions))
	case 12:
		return &r.PendingModelKey
	case 13:
		return (*int64)(unsafe.Pointer(&r.PendingDimensions))
	case 14:
		return &r.Version
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valueSettings(p unsafe.Pointer, c int32) any {
	r := (*airetrieval.Settings)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.MemoryEnabled
	case 4:
		return r.DocumentsEnabled
	case 5:
		return r.InboundMessagesEnabled
	case 6:
		return r.MonthlyIndexingBudgetUSD
	case 7:
		return r.Paused
	case 8:
		if r.PausedReason == "" {
			return nil
		}
		return string(r.PausedReason)
	case 9:
		if r.PausedAt == nil {
			return nil
		}
		return *r.PausedAt
	case 10:
		if r.ActiveModelKey == "" {
			return nil
		}
		return r.ActiveModelKey
	case 11:
		if r.Dimensions == 0 {
			return nil
		}
		return int64(r.Dimensions)
	case 12:
		if r.PendingModelKey == "" {
			return nil
		}
		return r.PendingModelKey
	case 13:
		if r.PendingDimensions == 0 {
			return nil
		}
		return int64(r.PendingDimensions)
	case 14:
		return r.Version
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

